mapper.select:
SELECT m.id, m.name, m.description, m.status, m.creator_id AS creatorId, cu.user_name AS creatorName, m.assignee_id AS assigneeId, au.user_name AS assigneeName, m.total_distance AS totalDistance, m.estimated_time AS estimatedTime, m.create_time AS createTime, m.modification_time AS modificationTime FROM waypoint_missions m LEFT JOIN users cu ON m.creator_id = cu.user_id LEFT JOIN users au ON m.assignee_id = au.user_id
AND m.creator_id = #{creatorId} AND m.assignee_id = #{assigneeId} AND m.name LIKE CONCAT('%',#{keyword},'%')
ORDER BY m.create_time DESC LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM waypoint_missions m

    AND m.creator_id = #{creatorId}
    AND m.assignee_id = #{assigneeId}
    AND m.name LIKE CONCAT('%',#{keyword},'%')

mapper.update:
UPDATE waypoint_missions
name = #{name}, description = #{description}, waypoints = #{waypoints}, total_distance = #{totalDistance}, estimated_time = #{estimatedTime}, modification_time = #{modificationTime}
WHERE id = #{id}
